--region import
---@type OverseaStoreUtils
local OverseaStoreUtils = import('Game.OverseaStore.OverseaStoreUtils')
---@type OverseaStoreMgr
local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
local SDKService = import('Game.Entry.SDKService')
--endregion import

--region define
local KTool = CS.Engine.Lib.KTool
local HideTimeDefine = 31536000 -- 策划要在限时商城配置非限时礼包，所以现在定义为，超过这个时限就隐藏时间，装作是非限时礼包
-- 页签类型
local TagType = {
    Discount  = 1, -- 折扣
    Recommend = 2, -- 推荐
    All       = 3, -- 折扣+推荐
}
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaMall/OverseaMallEventSpecialNode.prefab > name: OverseaMallEventSpecialNode
---@class OverseaStoreTimeLimitCell
---@field Env                           	OverseaStoreTimeLimitCell               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgNew                        	UnityEngine.RectTransform               
---@field FreeGroup                     	UnityEngine.RectTransform               
---@field Price1Icon                    	UnityEngine.RectTransform               
---@field Price2Icon                    	UnityEngine.RectTransform               
---@field Price1Text                    	UnityEngine.RectTransform               
---@field Price2Text                    	UnityEngine.RectTransform               
---@field Price1                        	UnityEngine.RectTransform               
---@field Price2                        	UnityEngine.RectTransform               
---@field ImgDiscountText               	UnityEngine.RectTransform               
---@field ImgTime                       	UnityEngine.RectTransform               
---@field TxtInventory                  	UnityEngine.RectTransform               
---@field ImgDiscount                   	UnityEngine.RectTransform               
---@field TxtTime                       	UnityEngine.RectTransform               
---@field TimeImgBg                     	UnityEngine.RectTransform               
