---@field ImgRecommend                  	UnityEngine.RectTransform               
---@field ImgGoodIcon                   	UnityEngine.RectTransform               
---@field FX_glow                       	UnityEngine.RectTransform               
---@field ImgBg                         	UnityEngine.RectTransform               
local OverseaStoreTimeLimitCell = Class("OverseaStoreTimeLimitCell")

--region lifecycle
function OverseaStoreTimeLimitCell:__init()
    self._storeType = nil
    self._cellData  = nil
end

function OverseaStoreTimeLimitCell:__delete()
    self._storeType = nil
    self._cellData  = nil
end

function OverseaStoreTimeLimitCell:Awake()
    CfUtils.SetImageAutoAlpha(self.ImgGoodIcon, true)
    self:InitHandler()
end

function OverseaStoreTimeLimitCell:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaStoreTimeLimitCell:InitHandler()
    SetButtonAction(self.BtnBuy, Bind(self, self.CellOnClickHandler))
end
--endregion init

--region handler
---cell点击回调
function OverseaStoreTimeLimitCell:CellOnClickHandler()
    xRecord.record("5-016", string.format('click_activity_%d', checkInt(self._cellData.icon)))
    local itemData = self._cellData
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(itemData.icon)
    local description  = goodsVo.name
    local payPoint = isNotNull(itemData.price) and itemData.price or itemData.payPoint

    local isFree = checkInt(itemData.isFree) == 1
    if isFree then
        OverseaStoreMgr:FreeBuyRequest(self._storeType, itemData)
    elseif checkInt(payPoint) == 0 then
        itemData.price = nil
        itemData.payPoint = nil
        OverseaStoreMgr:OpenBuyItemDialog(itemData, self._storeType , true)
    else
        SDKService:GetInstance():PayMoney({
            productId = itemData.productId,
            channelProductId = itemData.channelProductId,
            productDesc = description,
            payAmount = checkNumber(payPoint),
            data = itemData
        })
    end
end
--endregion handler

--region public
---刷新cell
---@param storeType OverseaStoreConstants.StoreType
---@param data table
function OverseaStoreTimeLimitCell:RefreshCell(storeType, data)
    self._storeType = storeType
    self._cellData = data

    self:RefreshCellState(data)
    self:RefreshTimeGroup(data)
    self:RefreshGoods(data)
    self:RefreshPrice(data)
    self:RefreshRewards(data)

end

---更新剩余时间显示
function OverseaStoreTimeLimitCell:UpdateTimeGroupText(data)
    local seconds = checkInt(data.endTime)
    if seconds <= 0 or seconds > HideTimeDefine then return end

    if seconds < 86400 then
        CfUtils.SetUISwitchImage(self.ImgTime, 2)
        CfUtils.SetUISwitchText(self.TxtTime, 2)
    else
        CfUtils.SetUISwitchImage(self.ImgTime, 1)
        CfUtils.SetUISwitchText(self.TxtTime, 1)
    end
    CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(seconds))
end
--endregion public

--region private
---刷新cell状态
function OverseaStoreTimeLimitCell:RefreshCellState(data)
    local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)
    KTool.SetActive(self.ButtonGroup, not isSoldOut)
    KTool.SetActive(self.Finish, isSoldOut)
end

---刷新剩余时间
function OverseaStoreTimeLimitCell:RefreshTimeGroup(data)
    local seconds = checkInt(data.endTime)
        
    if seconds <= 0 or seconds > HideTimeDefine then
        CfUtils.SetActive(self.Imgbg, false)
        CfUtils.SetActive(self.TxtTime, false)
        CfUtils.SetActive(self.TimeImgBg, false)
        return
    end

    CfUtils.SetActive(self.Imgbg, true)
    CfUtils.SetActive(self.TxtTime, true)

    self:UpdateTimeGroupText(data)
end

---刷新道具
function OverseaStoreTimeLimitCell:RefreshGoods(data)
    CfUtils.FillImage(self.ImgGoodIcon, CfUtils.GetImageFullPath(data.showImage))
    local name = data.name
    if checkInt(data.num) > 1 then
        name = string.format('%s x%d', name, checkInt(data.num))
    end
    CfUtils.FillText(self.TxtTitle, name)

    -- 品质
    local quality = math.max(1, checkInt(data.quality) - 2)
    CfUtils.SetUISwitchImage(self.ImgBg, quality)
    CfUtils.SetUISwitchParticleSystem(self.FX_glow, quality)

    -- 库存
    if checkNumber(data.stock) == -1 then
        KTool.SetActive(self.TxtInventory, false)
    else
        KTool.SetActive(self.TxtInventory, true)
        CfUtils.FillText(self.TxtInventory, localize("库存:") .. data.currentStock)
    end

    -- 售罄不显示标签
    local isSoldOut = OverseaStoreUtils.ProductIsSoldOut(data)
    if isSoldOut then
        CfUtils.SetActive(self.ImgDiscount, false)
        CfUtils.SetActive(self.ImgRecommend, false)
        CfUtils.SetActive(self.FX_glow, false)
        CfUtils.SetActive(self.ImgNew, OverseaStoreMgr:CheckTimeLimitGiftNew(data))
        return
    end
    
    local tabType = checkInt(data.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.ImgDiscountText, string.format('%s<size=30>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.ImgDiscount, true)
        CfUtils.SetActive(self.ImgRecommend, false)
        CfUtils.SetActive(self.FX_glow, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.ImgDiscount, false)
        CfUtils.SetActive(self.ImgRecommend, true)
        CfUtils.SetActive(self.FX_glow, true)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.ImgDiscountText, string.format('%s<size=30>%%</size>', checkInt(tonumber(data.iconTitle) * 100)))
        CfUtils.SetActive(self.ImgDiscount, true)
        CfUtils.SetActive(self.ImgRecommend, true)
        CfUtils.SetActive(self.FX_glow, true)
    else
        CfUtils.SetActive(self.ImgDiscount, false)
        CfUtils.SetActive(self.ImgRecommend, false)
        CfUtils.SetActive(self.FX_glow, false)
    end
    
    -- new 
    CfUtils.SetActive(self.ImgNew, OverseaStoreMgr:CheckTimeLimitGiftNew(data))
end

---刷新价格
function OverseaStoreTimeLimitCell:RefreshPrice(data)
    local isFree = checkInt(data.isFree) == 1
    CfUtils.SetActive(self.Price1, not isFree)
    CfUtils.SetActive(self.Price2, not isFree)
    CfUtils.SetActive(self.FreeGroup, isFree)
    CfUtils.SetUISwitchImage(self.BtnBuy, isFree and 2 or 1)
    if isFree then return end
    
    if checkInt(data.payPoint) > 0 then
        -- 货币购买
        CfUtils.SetActive(self.Price1, true)
        CfUtils.SetActive(self.Price1Icon, false)
        local windowsPriceId =  CfUtils.GetWindowsPriceId(data)
        CfUtils.FillText(self.Price1Text, CfUtils.GetCustomDisplayPrice(windowsPriceId, data.channelProductId, 30))
        if checkInt(data.original) > 0 then
            CfUtils.SetActive(self.Price2, true)
            CfUtils.SetActive(self.Price2Icon, false)
            CfUtils.FillText(self.Price2Text, CfUtils.GetDisplayPrice(data.original))
            CfUtils.SetUISwitchImage(self.Price2Text, 1)
        else
            CfUtils.SetActive(self.Price2, false)
        end
        return 
    end

    if not data.prices then return end
    local goodsId = checkNumber(data.prices[1].currency)
    if goodsId == Constants.Currency.PayDiamondId then
        CfUtils.SetUISwitchImage(self.BtnBuy, isFree and 2 or 1)
    else
        CfUtils.SetUISwitchImage(self.BtnBuy, 2)
    end
    local currencyVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    KTool.SetActive(self.Price1, true)
    CfUtils.SetActive(self.Price1Icon, true)
    CfUtils.FillImage(self.Price1Icon, currencyVo.photoPath)
    CfUtils.FillText(self.Price1Text, data.prices[1].current)
    if checkInt(data.prices[1].original) == 0 then
        KTool.SetActive(self.Price2, false)
    else
        KTool.SetActive(self.Price2, true)
        CfUtils.FillText(self.Price2Text, data.prices[1].original)
        CfUtils.SetUISwitchImage(self.Price2Text, 2)
        CfUtils.FillImage(self.Price2Icon, currencyVo.photoPath)
        CfUtils.SetActive(self.Price2Icon, true)
    end
end

---刷新奖励预览
function OverseaStoreTimeLimitCell:RefreshRewards(data)
    -----@type CommonGoodsListLight
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, OverseaStoreConstants.ScrPath.CommonGoodsListLight)
    scr:FreshBaseUI(data.rewards)
end
--endregion private

return OverseaStoreTimeLimitCell